// W1 · Plan — какие страницы поиска запрашивать.
// Нода: Code, режим «Run Once for All Items».
// Вход: нода «Any row» (Data Table → Get, Limit 1, Settings → Always Output Data = on).
//       Если таблица пустая, приходит пустой item без id.
// Первый запуск (таблица пустая) = бэкфилл: страницы 0 и 1, всё пишется со статусом seen.
// Обычный запуск: только страница 0 — 100 последних вакансий с запасом покрывают ночной интервал в 2 часа.
// startedAt — начало сбора для сообщения о сборе («Score job»).

const firstRun = !$input.first().json.id;
const pages = firstRun ? [0, 1] : [0];
const startedAt = Date.now();

return pages.map((page) => ({ json: { page, firstRun, startedAt } }));

// W1 · Parse search — разбор страниц поиска hh.ru в записи таблицы vacancies.
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы HTTP Request «Search hh», по одному на страницу (Response Format = Text,
//       Include Response Headers and Status = on).
// Выход: ОДИН item —
//   { ok: true,  firstRun, vacancies: [...], requests: [...] }  → IF «OK?» → Split Out
//   { ok: false, reason, html }                                → IF «OK?» → сохранить HTML → Stop and Error
// requests — запросы поиска для сообщения о сборе: { page, status, total (нашёл hh), count (на странице) }

const plan = $('Plan').all().map((i) => i.json);
const firstRun = Boolean(plan[0]?.firstRun);

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

const stripTags = (s) => String(s ?? '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const normTitle = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-zа-я0-9+#]+/g, ' ')
    .trim();

const fail = (reason, html) => [{ json: { ok: false, reason, html: String(html ?? '') } }];
// Текст ответа HTTP Request (Response Format = Text) n8n кладёт в поле data
const htmlOf = (res) => String(res.data ?? res.body ?? '');

// Формы оформления: tk = трудовой договор + SELF_EMPLOYED / INDIVIDUAL_ENTREPRENEUR / INDIVIDUAL_PERSON (ГПХ).
// Пустая строка = работодатель не указал
const contractOf = (v) =>
  [
    ...(v.acceptLaborContract ? ['tk'] : []),
    ...(v.civilLawContracts ?? []).flatMap((c) => c?.civilLawContractsElement ?? []).map((c) => c.toLowerCase()),
  ].join(',');

// Вакансия из выдачи → строка таблицы vacancies (имена полей = имена колонок)
function toRecord(v) {
  const pay = v.compensation ?? {};
  const companyId = v.company?.id ? String(v.company.id) : '';
  return {
    source: 'hh',
    external_id: String(v.vacancyId),
    // Одна вакансия в разных регионах = разные id. Склеиваем по компании и названию;
    // у скрытой компании id нет — такие не склеиваем
    dup_key: companyId ? `hh:${companyId}:${normTitle(v.name)}` : `hh:id:${v.vacancyId}`,
    title: String(v.name).trim(),
    company: String(v.company?.visibleName ?? v.company?.name ?? '').trim(),
    company_id: companyId,
    areas: v.area?.name ?? '',
    salary_from: pay.from ?? null,
    salary_to: pay.to ?? null,
    currency: pay.currencyCode ?? null,
    salary_gross: typeof pay.gross === 'boolean' ? pay.gross : null,
    experience: v.workExperience ?? '',
    employment_form: v.employmentForm ?? '',
    work_formats: (v.workFormats ?? []).flatMap((w) => w?.workFormatsElement ?? []).join(','),
    languages: (v.languages ?? [])
      .flatMap((l) => l?.language ?? [])
      .map((l) => `${l.isoCode}:${l.degree}`)
      .join(','),
    key_skills: stripTags(v.snippet?.skill),
    contract: contractOf(v),
    has_test: Boolean(v.userTestPresent),
    letter_required: Boolean(v['@responseLetterRequired']),
    responses: v.totalResponsesCount ?? null,
    snippet: [v.snippet?.req, v.snippet?.resp, v.snippet?.cond]
      .map(stripTags)
      .filter(Boolean)
      .join(' | ')
      .slice(0, 1500),
    url: `https://hh.ru/vacancy/${v.vacancyId}`,
    apply_url: `https://hh.ru/applicant/vacancy_response?vacancyId=${v.vacancyId}`,
    apply_type: 'hh',
    published_at: v.publicationTime?.$ ?? '',
    status: firstRun ? 'seen' : 'new',
  };
}

const byKey = new Map();
const seenIds = new Set();
const requests = [];

for (const [index, item] of $input.all().entries()) {
  const res = item.json;
  const html = htmlOf(res);

  if (res.statusCode !== 200) {
    const to = res.headers?.location ? ` → ${res.headers.location}` : '';
    return fail(`hh ответил HTTP ${res.statusCode}${to}`, html);
  }

  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) {
    // Слово «captcha» есть и на нормальной странице, поэтому смотрим на него только без InitialState
    const hint = /captcha|робот/i.test(html) ? 'похоже на капчу/блок' : 'сменилась вёрстка?';
    return fail(`Нет HH-Lux-InitialState — ${hint}`, html);
  }

  let state;
  try {
    state = JSON.parse(decodeEntities(tpl[1]));
  } catch (e) {
    return fail(`InitialState не разбирается: ${e.message}`, html);
  }

  const list = state?.vacancySearchResult?.vacancies;
  if (!Array.isArray(list)) return fail('Нет vacancySearchResult.vacancies — сменилась структура', html);
  requests.push({
    page: plan[index]?.page ?? index,
    status: res.statusCode,
    total: state.vacancySearchResult.totalResults ?? null,
    count: list.length,
  });

  for (const v of list) {
    if (!v?.vacancyId || !v?.name) return fail('У вакансии нет vacancyId/name — сменилась структура', html);
    const id = String(v.vacancyId);
    // Между запросами страниц вакансия может съехать со страницы 0 на страницу 1
    if (seenIds.has(id)) continue;
    seenIds.add(id);

    const rec = toRecord(v);
    const prev = byKey.get(rec.dup_key);
    if (!prev) byKey.set(rec.dup_key, rec);
    else if (rec.areas && !prev.areas.split(', ').includes(rec.areas)) prev.areas += `, ${rec.areas}`;
  }
}

// Пустая выдача по нашему запросу не бывает — считаем поломкой
if (byKey.size === 0) return fail('В выдаче 0 вакансий — сменилась структура или запрос', htmlOf($input.first().json));

return [{ json: { ok: true, firstRun, vacancies: [...byKey.values()], requests } }];

// W1 · Filter search — быстрые правила по данным выдачи, до захода на страницу вакансии.
// Нода: Code, режим «Run Once for All Items».
// Вход: новые вакансии из «Is new» и строки чёрного списка из «Blacklist».
// Выход: те же вакансии со status = new | rejected | seen и причиной в reasons.
// Правила — решения пользователя от 07.10.2026 (CLAUDE.md §7).

// AI-вакансия — разработка на LLM: агенты, RAG, интеграции нейросетей (решение пользователя 07.10.2026: берём
// в работу на любом стеке, нейросеть ставит apply). Общий код W1 «Filter search» (AI-названия не режут стоп-слова
// чужого стека и бэкенда) и «Parse vacancy» (AI-вакансии не режет правило «нет React и Vue»):
// строка «// @include n8n/shared/ai.js». Смотрим название и навыки, не описание: «пользуемся AI» пишут почти все.

// \b и \w в JS не работают с кириллицей — границы для русских слов задаём явно.
// ChatGPT в навыках — инструмент, а не разработка на AI: «gpt» после буквы не считается
const AI_LATIN = /(^|[^a-z])(ai|llm|llms|genai|gpt|rag|langchain|openai)([^a-z]|$)|agent/i;
// «агентство» — не AI
const AI_CYRILLIC = /(^|[^а-яё])(ии|нейросет[а-яё]*|агент(?!ств)[а-яё]*)([^а-яё]|$)/i;

const isAi = (text) => AI_LATIN.test(String(text ?? '')) || AI_CYRILLIC.test(String(text ?? ''));

const firstRun = Boolean($('Plan').first().json.firstRun);
const rows = $('Is new').all().map((i) => i.json);

// Чёрный список: в колонке company — точное название компании, как на hh (без учёта регистра
// и пробелов по краям), или её id на hh (только цифры).
// Форму организации не сравниваем: на странице вакансии hh пишет «ООО ОнТаргет ЛАБС», в выдаче — «ОнТаргет ЛАБС»
const ORG_FORM = /^(ооо|оао|зао|пао|ао|нао|ип|тоо|нко|ано|гуп|муп|фгуп|гку|гбу|llc|ltd|inc)\.?\s+|\s+(ооо|оао|зао|пао|ао|нао|ип|тоо|llc|ltd|inc)\.?$/g;
const norm = (s) => String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase().replace(ORG_FORM, '');
const blacklist = new Set(
  $('Blacklist')
    .all()
    .map((i) => norm(i.json.company))
    .filter(Boolean),
);

const inBlacklist = (r) => blacklist.has(norm(r.company)) || blacklist.has(String(r.company_id));

// \b и \w в JS не работают с кириллицей — границы слова и окончания задаём явно
const ru = (word) => new RegExp(`(^|[^а-яё])${word}([^а-яё]|$)`, 'i');

const RULES = [
  ['без опыта', (r) => r.experience === 'noExperience'],
  ['junior/стажёр', (r) => /junior|\bintern|trainee/i.test(r.title) || ru('(стаж[её]р|младш[а-яё]*|джун[а-яё]*)').test(r.title)],
  // Vue не отсекаем (решение пользователя 07.10.2026): только Vue — нейросеть ставит maybe, React + Vue — как React
  ['Angular', (r) => /angular/i.test(r.title)],
  [
    'Lead/архитектор',
    (r) =>
      (/\b(team ?lead|tech ?lead|lead|head|architect|cto)\b/i.test(r.title) ||
        ru('(тимлид[а-яё]*|техлид[а-яё]*|лид|архитектор[а-яё]*|руководител[а-яё]*)').test(r.title)) &&
      !/senior|middle/i.test(r.title) &&
      !ru('(старш[а-яё]*|ведущ[а-яё]*)').test(r.title),
  ],
  [
    'стоп-слово',
    (r) =>
      // Laravel, Symfony, Yii — тот же PHP (07.10.2026: «Laravel + Nuxt» пользователь отклонил)
      /php|laravel|symfony|\byii\b|wordpress|bitrix|\bqa\b|\b1c\b|teacher|tutor|instructor|o.?qituvchi/i.test(r.title) ||
      ru('(1с|битрикс[а-яё]*|преподавател[а-яё]*|тестировщик[а-яё]*|наставник[а-яё]*)').test(r.title),
  ],
  // Поиск frontend по всему тексту приносит чужой бэкенд (07.10.2026): режем по названию, в том числе fullstack
  // с таким бэкендом (пользователь отклонил «.Net/React»). AI-вакансии не трогаем — их берём на любом стеке
  [
    'чужой стек',
    (r) =>
      !isAi(r.title) &&
      (/\bruby\b|\brails\b|c#|\.net\b|\bdotnet\b|\bjava\b(?!\s*script)|\bgo(lang)?\b|\bdwh\b|data[\s-]*engineer/i.test(r.title) ||
        ru('(дата[\\s-]*инженер[а-яё]*)').test(r.title)),
  ],
  [
    'бэкенд',
    (r) =>
      !isAi(r.title) &&
      (/back[\s-]?end/i.test(r.title) || ru('(б[эе]к[\\s-]?[эе]нд[а-яё]*)').test(r.title)) &&
      !/full[\s-]?stack|front[\s-]?end/i.test(r.title) &&
      !ru('(фул+[\\s-]?ст[еэ]к[а-яё]*|фронт[\\s-]?[еэ]нд[а-яё]*)').test(r.title),
  ],
  ['> 3000 откликов', (r) => (r.responses ?? 0) > 3000],
  ['чёрный список', inBlacklist],
];

return rows.map((r) => {
  if (firstRun) return { json: { ...r, status: 'seen', reasons: '' } };
  const failed = RULES.filter(([, test]) => test(r)).map(([name]) => name);
  return { json: { ...r, status: failed.length ? 'rejected' : 'new', reasons: failed.join(', ') } };
});

// W1 · Parse vacancy — полная страница вакансии + правила, которым нужно описание.
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы HTTP Request «Vacancy page» — в том же порядке, что строки из «Is candidate»
//       (строки уже в таблице, у каждой есть id).
// Выход: строка целиком с обновлёнными status / reasons / description / key_skills / has_test / contract / error
//        → нода Update пишет её обратно по id. Дальше строки status = detailed оценивает нейросеть (W2).

const rows = $('Is candidate').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

// Общий код разбора страницы вакансии hh: W1 «Parse vacancy» и W6 «Archive status».
// В Code-ноду попадает строкой «// @include n8n/shared/hh.js».

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

// Ответ HTTP Request «Vacancy page» → { v: vacancyFull.vacancy, test } или { error, statusCode }
function parsePage(res) {
  const html = String(res.data ?? res.body ?? '');
  if (res.statusCode !== 200) return { error: `страница: HTTP ${res.statusCode}`, statusCode: res.statusCode };
  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) return { error: 'страница: нет HH-Lux-InitialState' };
  try {
    const state = JSON.parse(decodeEntities(tpl[1]));
    const v = state?.vacancyView?.vacancyFull?.vacancy;
    if (!v?.description) return { error: 'страница: нет описания' };
    return { v, test: state?.applicantVacancyResponseStatuses?.[String(v.vacancyId)]?.test };
  } catch (e) {
    return { error: `страница: ${e.message}` };
  }
}

// AI-вакансия — разработка на LLM: агенты, RAG, интеграции нейросетей (решение пользователя 07.10.2026: берём
// в работу на любом стеке, нейросеть ставит apply). Общий код W1 «Filter search» (AI-названия не режут стоп-слова
// чужого стека и бэкенда) и «Parse vacancy» (AI-вакансии не режет правило «нет React и Vue»):
// строка «// @include n8n/shared/ai.js». Смотрим название и навыки, не описание: «пользуемся AI» пишут почти все.

// \b и \w в JS не работают с кириллицей — границы для русских слов задаём явно.
// ChatGPT в навыках — инструмент, а не разработка на AI: «gpt» после буквы не считается
const AI_LATIN = /(^|[^a-z])(ai|llm|llms|genai|gpt|rag|langchain|openai)([^a-z]|$)|agent/i;
// «агентство» — не AI
const AI_CYRILLIC = /(^|[^а-яё])(ии|нейросет[а-яё]*|агент(?!ств)[а-яё]*)([^а-яё]|$)/i;

const isAi = (text) => AI_LATIN.test(String(text ?? '')) || AI_CYRILLIC.test(String(text ?? ''));

// Описание вакансии: HTML → текст с переносами строк
const htmlToText = (html) =>
  decodeEntities(
    String(html ?? '')
      .replace(/<\s*(br|\/p|\/li|\/h\d|\/div)[^>]*>/gi, '\n')
      .replace(/<li[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ''),
  )
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();

// «Работа только из РФ». Совпавший кусок пишем в reasons, чтобы ложные срабатывания было видно
const RF_ONLY = [
  /(только|исключительно)[^.\n]{0,40}(из|на территории|в|по)\s+(рф|росси)/i,
  /(находит[а-яё]*|проживать|проживани[а-яё]*|нахождени[а-яё]*|располож[а-яё]*)[^.\n]{0,30}(в|на территории|из)\s+(рф|росси)/i,
  /(налогов[а-яё]*\s+)?резидент[а-яё]*\s+(рф|росси)/i,
  /(based|located|reside\w*|living)\s+in\s+russia/i,
];

return rows.map((row, i) => {
  const page = parsePage(responses[i] ?? {});
  // Страница не открылась — вакансию не теряем: W2 оценит её по фрагменту из выдачи, ошибка видна в карточке
  if (page.error) return { json: { ...row, status: 'detailed', error: page.error } };

  const { v, test } = page;
  if (String(v.vacancyId) !== row.external_id) {
    return { json: { ...row, status: 'detailed', error: `страница: пришла вакансия ${v.vacancyId}` } };
  }

  const description = htmlToText(v.description);
  const skills = (v.keySkills ?? []).join(', ');
  const contract = [
    ...(v.acceptLaborContract ? ['tk'] : []),
    ...(v.civilLawContracts ?? []).flatMap((c) => c?.civilLawContractsElement ?? (typeof c === 'string' ? [c] : [])).map((c) => String(c).toLowerCase()),
  ].join(',');

  const reasons = [];
  if (v.status?.archived || v.closedForApplicants) reasons.push('в архиве');
  const rf = RF_ONLY.map((re) => description.match(re)).find(Boolean);
  if (rf) reasons.push(`только из РФ: «${rf[0].trim()}»`);
  // Vue (и Nuxt) — тоже наш стек с 07.10.2026: только Vue нейросеть оценит как maybe.
  // AI-вакансии (разработка на LLM) берём на любом стеке — решение пользователя 07.10.2026
  const ai = isAi(`${row.title} ${skills || row.key_skills}`);
  if (!ai && !/react|next\.?js|vue|nuxt/i.test(`${row.title} ${skills} ${description}`)) reasons.push('нет React и Vue');

  return {
    json: {
      ...row,
      description: description.slice(0, 8000),
      key_skills: skills || row.key_skills,
      has_test: Boolean(test?.hasTests ?? row.has_test),
      contract,
      status: reasons.length ? 'rejected' : 'detailed',
      reasons: reasons.join(', '),
      error: '',
    },
  };
});

// W1 · Score job — задание для W2 Score: оценить вакансии сразу после сбора и сообщить о сборе.
// Нода: Code, режим «Run Once for All Items». Стоит ниже ветки вакансий: n8n (execution order v1)
// выполняет её последней, когда новые вакансии уже detailed.
// Выход: один item { report } → «Score» (Execute Workflow, без ожидания). W2 сам берёт строки detailed
// из таблицы, а без этой ноды в W2 ушёл бы весь результат поиска со 100 вакансиями.
// report — блок «🔎 Сбор» (HTML): запросы к hh, что искали, сколько новых и что отсеял фильтр, следующий сбор.
// W2 шлёт его одним живым сообщением без звука (прошлое удаляет) или ставит сверху итога «📊 Оценено»
// (решения пользователя 07.10.2026).

// Поисковый запрос hh.ru (CLAUDE.md §5): параметры страницы /search/vacancy.
// Общий код scripts/build-workflows.mjs (ноды «Search hh» в W0 и W1) и W1 «Score job»
// (сообщение о сборе): строка «// @include n8n/shared/search.js».

const SEARCH_URL = 'https://hh.ru/search/vacancy';

// Слова поиска (решения пользователя 07.10.2026). frontend — по всему тексту вакансии: «JavaScript-разработчик»,
// fullstack и AI-вакансии с фронтендом в описании в названии слова frontend не несут; синонимы (фронтенд,
// front-end) hh подставляет сам. Стек и AI — только в названии: по всему тексту они приносят чужой бэкенд
// («React будет плюсом»). Замер за сутки: было 16 вакансий (всё в названии), стало 39
const SEARCH_ANYWHERE = ['frontend'];
const SEARCH_IN_NAME = [
  'react',
  'next.js',
  'nextjs',
  'vue',
  'vue.js',
  'vuejs',
  'nuxt',
  'nuxt.js',
  'nuxtjs',
  'typescript',
  // AI-разработка — тоже в работу (07.10.2026)
  'AI',
  'ИИ',
  'LLM',
  'GenAI',
  'GPT',
  'нейросети',
  'нейросетей',
];

const SEARCH_QUERY = [
  ['text', `${SEARCH_ANYWHERE.join(' OR ')} OR NAME:(${SEARCH_IN_NAME.join(' OR ')})`],
  ['professional_role', '96'],
  ['work_format', 'REMOTE'],
  ['education', 'not_required_or_not_specified'],
  // Только за сутки (решение пользователя 07.10.2026)
  ['search_period', '1'],
  ['order_by', 'publication_time'],
  ['items_on_page', '100'],
  ['enable_snippets', 'true'],
  // Как в выдаче на сайте; с одиночными значениями фильтров на результат не влияет
  ['ored_clusters', 'true'],
];

// Подписи параметров для сообщения о сборе, в порядке показа. Технические (items_on_page, enable_snippets,
// ored_clusters) не показываем
const SEARCH_LABELS = {
  work_format: { REMOTE: 'удалёнка' },
  professional_role: { 96: 'программист, разработчик' },
  education: { not_required_or_not_specified: 'образование не важно' },
  search_period: { 1: 'за сутки' },
  order_by: { publication_time: 'сначала новые' },
};

// Ссылка на ту же выдачу на hh (page — с нуля, как в запросе)
const searchUrl = (page = 0) =>
  `${SEARCH_URL}?${[...SEARCH_QUERY, ['page', String(page)]]
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
    .join('&')}`;

// Что искали, по-человечески: где какие слова и строка фильтров
function describeSearch() {
  const filters = Object.keys(SEARCH_LABELS).flatMap((key) =>
    SEARCH_QUERY.filter(([name]) => name === key).map(([, value]) => SEARCH_LABELS[key][value] ?? `${key}=${value}`),
  );
  return {
    words: `везде в тексте: ${SEARCH_ANYWHERE.join(' · ')}\nв названии: ${SEARCH_IN_NAME.join(' · ')}`,
    filters: filters.join(' · '),
  };
}

// Расписание сбора W1 по Москве (UTC+3, без перехода на летнее время), решение пользователя 07.10.2026:
// днём 07:00–17:30 каждые 30 мин, ночью 18, 20, 22, 00, 02, 04, 06 — 29 сборов в сутки.
// Держать в синхроне с Schedule W1 в scripts/build-workflows.mjs.
// Общий код W1 «Score job» (следующий сбор), W6 «Summary» и W7 «Render»: строка «// @include n8n/shared/schedule.js».

const COLLECT_STEP = 30 * 60 * 1000;

// Момент t (мс, кратен 30 мин) — сбор по расписанию?
function isCollectSlot(t) {
  const msk = new Date(t + 3 * 3600 * 1000);
  const h = msk.getUTCHours();
  const m = msk.getUTCMinutes();
  return h >= 7 && h < 18 ? m % 30 === 0 : m === 0 && h % 2 === 0;
}

// Сколько сборов по расписанию в промежутке (from, to]
function countCollectSlots(from, to) {
  let n = 0;
  for (let t = Math.floor(from / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP; t <= to; t += COLLECT_STEP) {
    if (isCollectSlot(t)) n++;
  }
  return n;
}

// Ближайший сбор по расписанию после момента t
function nextCollect(t) {
  let s = Math.floor(t / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP;
  while (!isCollectSlot(s)) s += COLLECT_STEP;
  return s;
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
// Ноды ветки вакансий выполняются, только если в выдаче нашлись новые
const all = (name) => {
  try {
    return $(name)
      .all()
      .map((i) => i.json);
  } catch {
    return [];
  }
};
const plural = (n, one, few, many) => {
  const d = n % 10;
  const dd = n % 100;
  if (d === 1 && dd !== 11) return one;
  return d >= 2 && d <= 4 && (dd < 12 || dd > 14) ? few : many;
};
// Время: по Таиланду (UTC+7), в скобках — по Москве (UTC+3), как в меню W7
const hhmm = (t, offset) => new Date(t + offset * 3600 * 1000).toISOString().slice(11, 16);
const thaiMsk = (t) => `${hhmm(t, 7)} (${hhmm(t, 3)} МСК)`;

const plan = $('Plan').first().json;
const search = $('Parse search').first().json;
const requests = search.requests ?? [];
const fresh = all('Filter search'); // новые: new | rejected, у бэкфилла seen
const parsed = all('Parse vacancy'); // прошли выдачу, страница открыта: detailed | rejected
const rejected = [...fresh, ...parsed].filter((r) => r.status === 'rejected');
const scoring = parsed.filter((r) => r.status === 'detailed').length;
const noPage = parsed.filter((r) => r.error).length;

// Запросы к hh: страницы поиска + страницы новых вакансий
const sent = requests.length + parsed.length;
let requestLine = `${sent} ${plural(sent, 'запрос', 'запроса', 'запросов')} к hh: поиск, ${requests
  .map((r) => `стр. ${r.page + 1} → ${r.status}`)
  .join(', ')}`;
if (parsed.length) {
  requestLine += ` · страницы вакансий: ${parsed.length}`;
  if (noPage) requestLine += ` (не открылись ${noPage} — оценка по фрагменту)`;
}

const onPages = requests.reduce((n, r) => n + (r.count ?? 0), 0);
const total = requests[0]?.total;
// Поиск за сутки (search_period=1): обычно всё найденное умещается на одной странице
const period = SEARCH_LABELS.search_period?.[SEARCH_QUERY.find(([key]) => key === 'search_period')?.[1]];
let result = 'все уже в базе';
if (search.firstRun) result = `первый запуск: ${fresh.length} записано без обработки (бэкфилл)`;
else if (fresh.length && !rejected.length) result = `новых ${fresh.length}, все на оценку`;
else if (fresh.length && !scoring) result = `новых ${fresh.length}, все отсеяны фильтром`;
else if (fresh.length) result = `новых ${fresh.length}: на оценку ${scoring}, отсеяно ${rejected.length}`;
const countLine = [
  total != null ? `hh нашёл${period ? ` ${period}` : ''} ${total}` : '',
  total == null || onPages < total ? `на ${requests.length > 1 ? 'страницах' : 'странице'} ${onPages}` : '',
  `без дублей ${search.vacancies?.length ?? 0} — ${result}`,
]
  .filter(Boolean)
  .join(', ');

// Отсеянные: название — ссылка на hh, причины. «только из РФ: «цитата»» показываем с цитатой — видно ложные срабатывания
const SHOW = 5;
const rejectedLines = rejected
  .slice(0, SHOW)
  .map((r) => `🚫 <a href="${esc(r.url)}">${esc(r.title)}</a> — ${esc(cut(String(r.reasons ?? ''), 120))}`);
if (rejected.length > SHOW) rejectedLines.push(`и ещё ${rejected.length - SHOW}`);

const { words, filters } = describeSearch();
const report = [
  `🔎 Сбор ${thaiMsk(plan.startedAt ?? Date.now())} · ${fresh.length ? `новых ${fresh.length}` : 'новых нет'}`,
  requestLine,
  countLine,
  ...rejectedLines,
  `<blockquote expandable>${esc(words)}\n${esc(filters)}</blockquote>`,
  `🔗 <a href="${esc(searchUrl(requests[0]?.page ?? 0))}">Открыть этот поиск на hh</a>`,
  `Следующий сбор ${thaiMsk(nextCollect(Date.now()))}`,
].join('\n');

return [{ json: { report } }];
